create table if not exists public."Laser_calibrations" (id uuid primary key default gen_random_uuid(), material text, operation text, machine text, thickness_mm numeric, power_percent numeric, speed_mm_s numeric, passes numeric, z_offset numeric, comments text, created_at timestamptz default now()); alter table public."Laser_calibrations" enable row level security; create policy if not exists laser_calib_read on public."Laser_calibrations" for select to anon using (true); create policy if not exists laser_calib_insert on public."Laser_calibrations" for insert to anon with check (true); grant usage on schema public to anon, authenticated; grant select,insert on public."Laser_calibrations" to anon, authenticated; notify pgrst, 'reload schema';